mapper.select:
SELECT COUNT(*) AS total_count, SUM(IF(app_type = 1, 1, 0)) AS cert_apply_count, SUM(IF(app_type = 2, 1, 0)) AS cert_renew_count, SUM(IF(app_type = 3, 1, 0)) AS cert_change_count, SUM(IF(app_type = 4, 1, 0)) AS info_change_count, SUM(IF(app_type = 5, 1, 0)) AS offline_count FROM biz_application a left join biz_institution_ext b on a.institution_id = b.dept_id where a.deleted = 0
and app_status = 1
and app_status = 5
and b.region = #{req.region}
and YEAR(a.create_time) = #{req.year}

select count(*) as total_count, SUM(CASE WHEN a.license_device_name = 'X线正电子发射断层扫描仪' THEN 1 ELSE 0 END) as petCtScanner, SUM(CASE WHEN a.license_device_name = '伽玛射线立体定向放射治疗系统' THEN 1 ELSE 0 END) as gammaRayStereotacticRtSystem, SUM(CASE WHEN a.license_device_name = '直线加速器' THEN 1 ELSE 0 END) as linearAccelerator, SUM(CASE WHEN a.license_device_name = '内窥镜手术器械控制系统' THEN 1 ELSE 0 END) as endoscopicSurgicalSystem, SUM(CASE WHEN a.license_device_name = '1.5T及以上磁共振成像系统' THEN 1 ELSE 0 END) as mriSystem1_5tPlus, SUM(CASE WHEN a.license_device_name = '64排及以上X线计算机断层扫描仪' THEN 1 ELSE 0 END) as ctScanner64SlicePlus FROM biz_license_original a left join biz_application b on a.application_id = b.id left join biz_institution_ext c on b.institution_id = c.dept_id where a.deleted = 0
and c.region = #{req.region}
and YEAR(a.create_time) = #{req.year}

select count(a.id) as total, SUM(IF(a.status = '已发布', 1, 0)) AS publishedCount, SUM(IF(a.status = '未发布', 1, 0)) AS draftCount, (SELECT COUNT(*) FROM biz_user_notification_status WHERE is_read = b'1') AS totalViews from biz_notifications a left join biz_application b on a.app_id = b.id left join biz_institution_ext c on b.institution_id = c.dept_id where a.deleted = 0
and c.region = #{req.region}
and YEAR(a.create_time) = #{req.year}

select a.region, a.institution_name, b.license_device_name, b.ladder_config_model,
       b.license_no, b.issue_date, c.installation_date, c.production_enterprise,
       c.specific_model, c.duplicate_issue_date, b.status
from biz_application d
left join biz_institution_ext a on d.institution_id = a.dept_id
left join biz_license_original b on b.application_id = d.id
left join biz_license_duplicate c on b.id = c.original_id
where d.app_status = 5

    and a.region = #{req.region}


    and a.region in ('铜川市', '渭南市', '安康市', '商洛市', '延安市', '榆林市')


    and c.acceptance_status = #{req.acceptanceStatus}


    and a.institution_type = 1


    and a.institution_type in (2, 3, 4)


    and YEAR(b.create_time) = #{req.year}


    and b.create_time between #{req.startDate} and #{req.endDate}


    and b.license_device_name in

        #{item}



    and b.status = #{req.status}


    and (
        (a.institution_name like concat('%', #{req.keywords}, '%')
    or b.license_no like concat('%', #{req.keywords}, '%')
         )

SELECT count(b.id) as num, a.region, b.license_device_name, case when a.institution_type = 1 then '社会办医' else '政府办医' END AS institution_type_label, SUM(CASE WHEN d.acceptance_status = 1 THEN 1 ELSE 0 END) as accepted, SUM(CASE WHEN d.acceptance_status = 0 THEN 1 ELSE 0 END) as not_accepted FROM biz_institution_ext a LEFT JOIN biz_application b ON a.dept_id = b.institution_id left join biz_license_original c on b.id = c.application_id left join biz_license_duplicate d on c.id = d.original_id where b.app_status = 5 and b.deleted = 0
and a.region = #{req.region}
and a.region in ('铜川市', '渭南市', '安康市', '商洛市', '延安市', '榆林市')
and b.license_device_name in
#{item}
and c.acceptance_status = #{req.acceptanceStatus}
and a.institution_type = 1
and a.institution_type in (2, 3, 4)
GROUP BY a.region, b.license_device_name
